import {Timeline} from '../structure/Timeline.jsx';
import {MemoryCreationFields} from '../../shared/MemoryCreationFields.jsx';
import {resourceCache,resourceKey} from '../../shared/resource-cache.js';
import {relationColors,relationKinds} from '../structure/Timeline.jsx';
import {StructuredCard} from '../../shared/StructuredCard.jsx';
import {CardQuickSettings} from '../../shared/CardQuickSettings.tsx';
import {CardQuickButton,CardLegend} from '../../shared/card-appearance.tsx';
import {ReferenceButton} from '../../shared/collaboration.tsx';
import {OverviewPage,DetailPage,DetailActions,useDetailTrail} from '../../shared/detail-page.tsx';
import {DocumentTextarea} from '../../shared/workspace.tsx';
import {CreateDocument} from '../../shared/creation.tsx';
import {RelationCanvas} from './RelationCanvas.tsx';
import {Modal,useWorkbenchPreferences} from '../../shared/preferences.tsx';
import {ViewSwitch,FilterControl,SearchControl} from '../../shared/workspace.tsx';
import {Groups, GroupSelect, filterGroup} from '../../shared/groups.tsx';
import {BatchManager,BatchList} from '../../shared/batch-management.tsx';
import React,{useEffect,useRef,useState,useContext} from 'react';
import {useDialog} from '../../dialog.tsx';
import {useDraft,useResource,usePreference,SessionScope} from '../../shared/state.js';
import {ResourceState,SaveBar,saveShortcut} from '../../shared/ui.jsx';

const kind=n=>n.type==='character_card'?'角色卡':'世界书';
export function Memory({call,novelId,tick,run,busy,onTransfer,onChapter,onEvent,onForeshadow,onPlanning}) {
 const {preferences}=useWorkbenchPreferences();
 const scope=useContext(SessionScope),[area,setArea]=usePreference(`${novelId}:memory-area`,'library');
 const [stage,setStage]=usePreference(`${novelId}:relationship-stage`,'base');
 const [quick,setQuick]=useState(null);
 const {confirm}=useDialog();
 const [view,setView]=useState(preferences.memoryView),[batch,setBatch]=useState(false),[creating,setCreating]=useState(null);
 const [selected,setSelected]=usePreference(`${novelId}:memory-selected`,null);
 const [node,setNode]=useState(()=>resourceCache.get(resourceKey(scope,`${novelId}:memory-detail:${selected}`))?.value||null),[edge,setEdge]=useState(null),[query,setQuery]=useState(''),[filter,setFilter]=useState(''),[group,setGroup]=useState(''),[checked,setChecked]=useState([]),[error,setError]=useState(''),[poll,setPoll]=useState(0);
 const request=useRef(0),canvas=useRef(null),batchView=useRef(view);
 const trail=useDetailTrail(node?.id||null);
 const resource=useResource(()=>area==='library'?Promise.all([call('graph.list',{novelId,...(query?{query}:{}),...(group?{groupId:filterGroup(group)}:{})}),call('edge.list',{novelId}),call('graph.groups',{novelId})]):Promise.resolve([[],[],[]]),[call,novelId,tick,poll,query,group,area],`${novelId}:memory:${query}:${group}:${area}`);
 const [nodes=[],edges=[],groups=[]]=resource.value||[];
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)setPoll(v=>v+1);},5000);return()=>{clearInterval(timer);request.current++;};},[]);
 const open=async (id,back=false)=>{const seq=++request.current;setArea('library');setError('');const key=resourceKey(scope,`${novelId}:memory-detail:${id}`),cached=resourceCache.get(key);if(cached){setNode(cached.value);setSelected(id);}const epoch=resourceCache.epoch();try{const data=await call('graph.get',{novelId,nodeId:id});resourceCache.put(key,data,epoch);if(seq===request.current){if(back)trail.back(id);else trail.visit(id);setNode(data);setSelected(id);setEdge(null);}}catch(e){if(seq===request.current)setError(e.message);}};
 useEffect(()=>{if(selected)open(selected);},[]);
 const create=(type,position,connection)=>setCreating({type,position:position||canvas.current?.(),connection:connection?{...connection,expectedRevision:allNodes.find(n=>n.id===connection.id)?.revision}:undefined});
 const saved=n=>{if(n)trail.visit(n.id);else trail.clear();setNode(n);setSelected(n?.id||null);};
 const all=useResource(()=>area==='library'?call('graph.list',{novelId}):Promise.resolve([]),[call,novelId,tick,poll,area],`${novelId}:memory-all:${area}`);
 const merged=new Map();for(const n of [...(all.value||[]),...nodes])if(!merged.has(n.id)||merged.get(n.id).revision<=n.revision)merged.set(n.id,n);
 const allNodes=[...merged.values()];
 const stageResource=useResource(()=>view==='canvas'&&area==='library'?Promise.all([call('writing.relationship.list',{novelId,phase:['base','latest'].includes(stage)?stage:'event',eventId:['base','latest'].includes(stage)?undefined:stage}),call('writing.event.list',{novelId})]).then(values=>[...values,stage]):Promise.resolve([[],[],stage]),[call,novelId,stage,tick,poll,view,area],`${novelId}:relationship:${stage}`);
 const projected=stageResource.value?.[2]===stage?stageResource.value[0]:[],events=stageResource.value?.[1]||[];
 const related=edges.filter(e=>e.from===node?.id||e.to===node?.id);
 const visible=nodes.filter(n=>!filter||n.type===filter);
 const batchItems=visible.map(n=>({id:n.id,title:n.name,summary:n.summary,meta:[kind(n),groups.find(g=>g.id===n.groupId)?.name].filter(Boolean).join(' · ')}));
 const beginBatch=()=>{batchView.current=view;setBatch(true);setChecked([]);setView('list');};
 const endBatch=()=>{setBatch(false);setChecked([]);setView(batchView.current);};
 const clear=()=>{setQuery('');setFilter('');setGroup('');};
 const close=()=>{if(trail.previous){void open(trail.previous,true);return;}request.current++;trail.clear();setNode(null);setEdge(null);setSelected(null);};
 const connect=(from,to)=>setEdge({from,to,name:'',content:''});
 const connectDirect=(from,to)=>run(()=>call('edge.create',{novelId,from,to,name:'',content:'',requestId:crypto.randomUUID()}));
 const saveLayout=(points,revisions={},requestId=crypto.randomUUID())=>run(()=>call('graph.layout',{novelId,requestId,positions:Object.entries(points).map(([nodeId,position])=>({nodeId,position,expectedRevision:revisions[nodeId]??allNodes.find(n=>n.id===nodeId)?.revision}))}));
 const disconnect=items=>run(()=>call('edge.disconnect',{novelId,requestId:crypto.randomUUID(),confirm:true,edges:items.map(e=>({id:e.id,expectedRevision:e.revision}))}));
 const removeNodes=async ids=>{if(ids.length&&!busy&&await confirm(`删除选中的 ${ids.length} 张设定卡片及其关系？`))await run(()=>call('graph.remove',{novelId,requestId:crypto.randomUUID(),confirm:true,members:ids.map(id=>({id,expectedRevision:allNodes.find(n=>n.id===id)?.revision}))}));};
 const duplicateNodes=(ids,points={})=>run(()=>call('graph.duplicate',{novelId,requestId:crypto.randomUUID(),members:ids.map(id=>({id,expectedRevision:allNodes.find(n=>n.id===id)?.revision,...(points[id]?{position:points[id]}:{})}))}));
 const moveNodes=(ids,groupId)=>run(()=>call('graph.move',{novelId,requestId:crypto.randomUUID(),groupId,members:ids.map(id=>({id,expectedRevision:allNodes.find(n=>n.id===id)?.revision}))}));
 if(creating)return <CreateDocument draftKey={`${novelId}:memory-create:${creating.type}:${creating.connection?.id||'new'}`} nameLabel={creating.type==='character_card'?'姓名':'名称'} extraFields={(draft,change)=><MemoryCreationFields kind={creating.type} {...{draft,change}}/>} label={creating.type==='character_card'?'新建角色卡':'新建世界书'} context={creating.connection?'创建后自动连接到原设定':undefined} initial={{title:'',summary:'',content:'',values:{},aliasesText:'',groupId:filterGroup(group)||allNodes.find(n=>n.id===creating.connection?.id)?.groupId||null}} {...{groups,busy}} close={()=>setCreating(null)} createGroup={async name=>{let result;await run(async()=>{result=await call('graph.group.create',{novelId,name});});return result;}} save={(value,requestId)=>run(async()=>{const fields={type:creating.type,name:value.title,summary:value.summary,content:value.content,groupId:value.groupId,values:Object.fromEntries(Object.entries(value.values||{}).filter(([,v])=>v!=='')),aliases:(value.aliasesText||'').split(/[,，\n]/).map(s=>s.trim()).filter(Boolean),...(creating.position?{position:creating.position}:{})};const result=await call('writing.card.create',{novelId,requestId,...fields,connection:creating.connection});saved(result.node||result);})}/>;
 if(area==='story'&&!node)return <div className="memory-workspace connected-workspace"><div className="connected-nav"><button onClick={()=>setArea('library')}>资料库与关系图</button><button className="selected">故事演变</button></div><div className="connected-scroll"><Timeline {...{call,novelId,tick,run,busy,onChapter,onForeshadow,onPlanning}} onMemory={open}/></div></div>;
 return <div className="memory-workspace"><OverviewPage active={!node}><header className="module-heading canvas-heading"><div className="connected-nav"><button className="selected">资料库与关系图</button><button onClick={()=>{setNode(null);setSelected(null);setArea('story');}}>故事演变</button></div><div className="module-toolbar">
 <Groups {...{groups,busy,call,run,novelId}} prefix="graph" value={group} onChange={value=>{setGroup(value);setChecked([]);}}/>
 <FilterControl label="类型" value={filter} change={setFilter}><option value="">全部类型</option><option value="character_card">角色卡</option><option value="world_entry">世界书</option></FilterControl>
 <span className="toolbar-spacer"/><SearchControl label="搜索设定" value={query} change={setQuery}/>{!batch&&<><ViewSwitch value={view} change={setView} graph="画布"/>
 <button className="module-select" aria-label="多选" disabled={busy} onClick={beginBatch}>多选</button><details className="menu"><summary className="primary">＋ 设定</summary><div className="menu-panel"><button disabled={busy} onClick={()=>create('character_card')}>新建角色卡</button><button disabled={busy} onClick={()=>create('world_entry')}>新建世界书</button></div></details>
 <details className="menu"><summary aria-label="设定更多操作">···</summary><div className="menu-panel"><button disabled={busy} onClick={()=>onTransfer({mode:'import',selection:{kind:'memory',novelId}})}>导入设定</button><button disabled={busy} onClick={()=>onTransfer({mode:'export',selection:{kind:'memory',novelId,nodeIds:visible.map(n=>n.id)}})}>导出当前设定范围</button></div></details></>}
 </div><CardLegend/>{view==='canvas'&&<><div className="row timeline-toolbar"><label>关系阶段 <select aria-label="关系图阶段" value={stage} onChange={e=>setStage(e.target.value)}><option value="base">基础关系</option><option value="latest">最新关系</option>{events.map(e=><option key={e.id} value={e.id}>{e.storyTime} · {e.title}</option>)}</select></label><button onClick={()=>onEvent(null)}>打开故事演变</button>{stage!=='base'&&<small>阶段图供查看；编辑连线修改的是基础关系。</small>}</div>{stageResource.error&&<p className="notice error">{stageResource.error}<button onClick={()=>setStage('base')}>返回基础关系</button></p>}<div className="relation-legend">{Object.entries(relationKinds).map(([id,label])=><span key={id} style={{color:relationColors[id]}}>━ {label}</span>)}</div></>}{(query||group||filter)&&<div className="active-filters"><button onClick={clear}>清除筛选 <span aria-hidden="true">×</span></button></div>}</header>
 <div className="memory-layout"><div className="memory-overview">{batch&&<BatchManager items={batchItems} selected={checked} change={setChecked} groups={groups} busy={busy||resource.loading} done={endBatch} onMove={(ids,groupId)=>run(async()=>{await call('graph.move',{novelId,groupId,members:ids.map(id=>({id,expectedRevision:allNodes.find(n=>n.id===id)?.revision}))});setChecked([]);})}/>}<ResourceState resource={resource}>
 {batch?<BatchList items={batchItems} selected={checked} change={setChecked} busy={busy||resource.loading}/>:view==='canvas'?<RelationCanvas key={novelId} scopeKey={`${novelId}:settings`} nodes={visible} allNodes={allNodes} edges={projected.filter(e=>e.active)} groups={groups} busy={busy} onReady={center=>{canvas.current=center;}} onNew={(position,connection,type)=>create(type||allNodes.find(n=>n.id===connection?.id)?.type||'character_card',position,connection)} onQuick={setQuick} onSelect={open} onConnect={connectDirect} onLayout={saveLayout} onEdit={e=>setEdge(edges.find(b=>b.id===e.id))} onDelete={disconnect} onRemove={removeNodes} onDuplicate={duplicateNodes} onMove={moveNodes}/>:!visible.length?<div className="empty">{query||filter||group?'没有匹配的设定，试试调整筛选。':'添加第一张角色卡或世界书。'}</div>:<div className="library-list">{visible.map(n=><div className="selectable-entry" key={n.id}><CardQuickButton title={n.name} open={()=>setQuick(n.id)} disabled={busy}/><button className={`library-entry kind-${n.type==='character_card'?'character':'world'} ${trail.lastOpened===n.id?'selected':''}`} aria-current={trail.lastOpened===n.id?'true':undefined} onClick={()=>open(n.id)}><span className="entry-heading"><strong>{n.name}</strong><small>{kind(n)}</small></span>{n.cardTags?.length>0&&<span className="card-tags">{n.cardTags.map(tag=><small key={tag}>{tag}</small>)}</span>}{n.summary&&<p>{n.summary}</p>}{n.groupId&&<small>{groups.find(g=>g.id===n.groupId)?.name}</small>}</button></div>)}</div>}</ResourceState></div></div></OverviewPage>
 {quick&&<CardQuickSettings kind="memory" id={quick} {...{call,novelId,groups,run,busy}} close={()=>setQuick(null)} updated={()=>{setPoll(n=>n+1);}} openDetail={()=>open(quick)}/>}
 {error&&<p className="notice error" role="alert">{error}</p>}
 {node&&<DetailPage key={node.id} className="memory-detail" backLabel={trail.previous?'‹ 返回上一条':'‹ 返回设定'} onBack={close}><NodeEditor key={node.id||node.type} {...{call,novelId,tick,run,busy,saved,groups,onTransfer,onChapter,onEvent}} initial={node} latest={allNodes.find(n=>n.id===node.id)}/>
 {node.id&&<section className="section-fold"><div className="row"><h3 className="grow">相关设定</h3><button disabled={busy||allNodes.length<2} onClick={()=>connect(node.id,allNodes.find(n=>n.id!==node.id)?.id)}>添加关系</button></div>{related.map(e=><div key={e.id} className="related-entry"><button onClick={()=>open(e.from===node.id?e.to:e.from)}>{allNodes.find(n=>n.id===(e.from===node.id?e.to:e.from))?.name||'设定'}</button>{e.name&&<small>{e.name}</small>}{e.content&&<p>{e.content}</p>}<button aria-label={`修改关系 ${e.name||'连线'}`} onClick={()=>setEdge(e)}>···</button></div>)}</section>}
 </DetailPage>}{edge&&<Modal title={edge.id?'编辑关系':'添加关系'} close={()=>setEdge(null)}><EdgeEditor key={edge.id||`new:${edge.from}:${edge.to}`} {...{call,novelId,run,busy}} nodes={allNodes} initial={edge} saved={()=>setEdge(null)}/></Modal>}</div>;
}

function NodeEditor({call,novelId,tick,run,busy,initial,latest,saved,groups,onTransfer,onChapter,onEvent,onForeshadow,onPlanning}) {
 const {value,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:node:${initial.id||initial.type+':new'}`,initial);
  const fresh=useResource(()=>initial.id?call('graph.get',{novelId,nodeId:initial.id}):Promise.resolve(null),[call,novelId,initial.id,latest?.revision],`${novelId}:memory-detail:${initial.id}`);
  useEffect(()=>{if(!busy&&!dirty&&fresh.value?.revision>base.revision){accept(fresh.value);saved(fresh.value);}},[fresh.value,busy,dirty,base.revision]);
 const [editing,setEditing]=useState(!initial.id||dirty);const {confirm,ask}=useDialog();
 const set=(key,v)=>change(old=>({...old,[key]:v}));
 const save=()=>{if(!value.name.trim()||busy)return;run(async()=>{const result=await call(value.id?'graph.update':'graph.create',{novelId,nodeId:value.id,expectedRevision:base.revision,type:value.type==='character_card'?'character_card':'world_entry',groupId:value.groupId||null,name:value.name,summary:value.summary||'',content:value.content||''});accept(result);saved(result);setEditing(false);});};
 return <div onKeyDown={e=>saveShortcut(e,save)}><h2>{value.name||`新${kind(value)}`}</h2><DetailActions><ReferenceButton reference={{kind:'memory',novelId,id:value.id,title:value.name,revision:base.revision,dirty}}/><button onClick={()=>setEditing(!editing)}>{editing?'阅读':'编辑'}</button></DetailActions>{fresh.error&&<p className="notice error" role="alert">{fresh.error}</p>}{latest&&latest.revision!==base.revision&&<p className="notice">设定已有新版本，本地草稿仍保留。保存会检查冲突。</p>}
 {editing?<fieldset disabled={busy} className="editor-fields document-fields"><label>类型<select value={value.type==='character_card'?'character_card':'world_entry'} onChange={e=>set('type',e.target.value)}><option value="character_card">角色卡</option><option value="world_entry">世界书</option></select></label><div className="creation-settings"><GroupSelect groups={groups} value={value.groupId} onChange={id=>set('groupId',id)}/><button type="button" disabled={busy} onClick={async()=>{const name=await ask('新建分组名称');if(name?.trim())run(async()=>{const g=await call('graph.group.create',{novelId,name});set('groupId',g.id);});}}>＋ 新建分组</button></div><label>名称<input value={value.name} onChange={e=>set('name',e.target.value)}/></label><label>摘要<DocumentTextarea aria-label="摘要" value={value.summary||''} onChange={e=>set('summary',e.target.value)}/></label><label>全文<DocumentTextarea aria-label="全文" className="prose" value={value.content||''} onChange={e=>set('content',e.target.value)}/></label></fieldset>:<><p className="document-summary">{value.summary||'暂无摘要'}</p><article className="document-body">{value.content||'暂无内容'}</article></>}
 {(editing||dirty)&&<SaveBar dirty={dirty||!value.id} {...{busy}} error={cacheError} invalid={!value.name.trim()?'请填写名称':null} onSave={save} label="保存设定"/>}
 {value.id&&<StructuredCard {...{call,novelId,tick,busy,run,onChapter,onEvent}} nodeId={value.id}/>}
 {value.id&&<details className="section-fold"><summary>更多操作</summary><button disabled={busy||dirty} title={dirty?'先保存设定后导出':undefined} onClick={()=>onTransfer({mode:'export',selection:{kind:'memory',novelId,nodeIds:[value.id]}})}>导出这条设定</button><button disabled={busy} onClick={async()=>{if(!dirty||await confirm('放弃本地草稿并读取最新设定？'))run(async()=>{const n=await call('graph.get',{novelId,nodeId:value.id});accept(n);saved(n);});}}>读取最新</button><button className="danger" disabled={busy} onClick={async()=>{if(await confirm(`删除“${value.name}”及其关系？`))run(async()=>{await call('graph.delete',{novelId,nodeId:value.id,expectedRevision:base.revision,confirm:true});accept(initial);saved(null);});}}>删除设定</button></details>}
 </div>;
}
function EdgeEditor({call,novelId,nodes,run,busy,initial,saved}) {
  const {value:draft,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:edge:${initial.id||`new:${initial.from}:${initial.to}`}`,initial);
  const {confirm,ask}=useDialog();
  const save=()=>{if(draft.from&&draft.to&&!busy)run(async()=>{const e=await call(draft.id?'edge.update':'edge.create',{from:draft.from,to:draft.to,name:draft.name,content:draft.content,novelId,edgeId:draft.id,expectedRevision:base.revision});accept(e);saved(e);});};
  return <div onKeyDown={e=>saveShortcut(e,save)}><fieldset disabled={busy} className="editor-fields">{[['from','从'],['to','到']].map(([key,label])=><label key={key}>{label}<select value={draft[key]} onChange={e=>change(d=>({...d,[key]:e.target.value}))}>{nodes.map(n=><option key={n.id} value={n.id}>{n.name}</option>)}</select></label>)}<label>关系名称（可选）<input placeholder="例如：居住于、朋友、敌对" value={draft.name||''} onChange={e=>change(d=>({...d,name:e.target.value}))}/></label><label>说明<DocumentTextarea value={draft.content||''} onChange={e=>change(d=>({...d,content:e.target.value}))}/></label></fieldset><SaveBar dirty={dirty||!draft.id} {...{busy}} error={cacheError} invalid={!draft.from||!draft.to?"请选择关系端点":null} onSave={save} label="保存关系"/>{draft.id&&<details><summary>更多操作</summary><button disabled={busy} onClick={async()=>{if(!dirty||await confirm("丢弃关系草稿并读取最新版本？"))run(async()=>{const latest=await call("edge.get",{novelId,edgeId:draft.id});accept(latest);saved(latest);});}}>读取最新关系</button><button disabled={busy} className="danger" onClick={async()=>{if(await confirm('删除这条关系？'))run(async()=>{await call('edge.delete',{novelId,edgeId:draft.id,expectedRevision:base.revision,confirm:true});accept(initial);saved(null);});}}>删除关系</button></details>}</div>;
}
